using Roentgen.Contracts;
using Roentgen.Core;
using Roentgen.Factions;
using FactionReputationDimension = Roentgen.Factions.ReputationDimension;
using Roentgen.Items;
using Roentgen.Persistence;

namespace Roentgen.Factions.Tests;

public sealed class Phase15SystemTests
{
    private static readonly CampaignSeed Seed = new(0x524F454E5447454EUL);
    private static readonly StableId PlayerId = StableIdFactory.Create("phase15-test", "player");

    [Fact] public void Generator_is_deterministic_and_creates_complete_regression_society() { SocietyWorldState first = Phase15Content.CreateRegressionWorld(Seed, PlayerId); SocietyWorldState second = Phase15Content.CreateRegressionWorld(Seed, PlayerId); Assert.Equal(first.ComputeChecksum(), second.ComputeChecksum()); Assert.Equal(3, first.Factions.Count); Assert.Equal(3, first.Settlements.Count); Assert.All(first.Factions, faction => Assert.NotEmpty(faction.ControlledSettlements)); }
    [Fact] public void Society_snapshot_round_trips_with_identical_checksum() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); byte[] bytes = SocietyWorldSnapshotSerializer.WriteToBytes(world); SocietyWorldState restored = SocietyWorldSnapshotSerializer.ReadFromBytes(bytes); Assert.Equal(world.ComputeChecksum(), restored.ComputeChecksum()); }
    [Fact] public void Trade_is_bilateral_and_conservative() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); SettlementState exporter = world.GetSettlement(Phase15Content.RedQuarrySettlementId); long before = exporter.GetStock(SocietyCommodity.Metals).QuantityMilliunits; var engine = new SocietySimulationEngine(Seed); _ = engine.AdvanceDay(world); Assert.True(exporter.GetStock(SocietyCommodity.Metals).QuantityMilliunits < before); TradeShipmentState shipment = world.Shipments.First(value => value.ExporterSettlementId == exporter.Id && value.ImporterSettlementId == Phase15Content.ProspectSettlementId && value.Commodity == SocietyCommodity.Metals); _ = engine.AdvanceDays(world, 3); Assert.True(shipment.DeliveredMilliunits + shipment.LostMilliunits <= shipment.LoadedMilliunits); }
    [Fact] public void Services_stop_without_declared_inputs() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); SettlementState prospect = world.GetSettlement(Phase15Content.ProspectSettlementId); _ = prospect.GetStock(SocietyCommodity.Medicine).Consume(long.MaxValue); _ = new SocietySimulationEngine(Seed).AdvanceDay(world); Assert.Contains(prospect.Services, value => value.Kind == SettlementServiceKind.MedicalCare && !value.Operating); }
    [Fact] public void Leadership_vacancy_selects_a_deterministic_successor() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); LeadershipState leadership = world.GetLeadership(FactionIds.ProspectClinicCompact); leadership.VacateLeader(world.Day); _ = new SocietySimulationEngine(Seed).AdvanceDay(world); Assert.NotNull(leadership.HighestOffice); Assert.False(leadership.HighestOffice!.Vacant); Assert.False(leadership.HighestOffice.HolderActorId.IsEmpty); }
    [Fact] public void Crime_requires_witness_or_evidence_before_report() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var crime = new CrimeRecordState(StableIdFactory.Create("test", "crime"), CrimeKind.Theft, FactionIds.ProspectClinicCompact, Phase15Content.ProspectSettlementId, PlayerId, 400, 0); world.AddCrime(crime); _ = new SocietySimulationEngine(Seed).AdvanceDay(world); Assert.Equal(CrimeStatus.Unreported, crime.Status); SocietyValidationReport report = new SocietyValidator().Validate(world); Assert.DoesNotContain(report.Issues, value => value.Code == "crime.omniscient-report"); }
    [Fact] public void Witnessed_crime_generates_warrant_and_reputation_evidence() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); StableId id = StableIdFactory.Create("test", "witnessed-crime"); var crime = new CrimeRecordState(id, CrimeKind.Sabotage, FactionIds.BlackwaterRecoveryAuthority, Phase15Content.BlackwaterSettlementId, PlayerId, 800, 0); crime.AddWitness(StableIdFactory.Create("test", "witness"), 900); world.AddCrime(crime); _ = new SocietySimulationEngine(Seed).AdvanceDay(world); Assert.Equal(CrimeStatus.WarrantIssued, crime.Status); Assert.True(world.GetOrCreateReputation(PlayerId, FactionIds.BlackwaterRecoveryAuthority)[FactionReputationDimension.KnownCrimeSeverity] > 0); }
    [Fact] public void Reputation_evidence_is_applied_exactly_once() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var evidence = new ReputationEvidenceState(StableIdFactory.Create("test", "evidence-once"), PlayerId, FactionIds.ProspectClinicCompact, StableIdFactory.Create("test", "witness"), FactionReputationDimension.Trust, 200, 1000, 1000, world.Day, "aid witnessed"); world.AddReputationEvidence(evidence); var engine = new SocietySimulationEngine(Seed); _ = engine.AdvanceDay(world); int once = world.GetOrCreateReputation(PlayerId, FactionIds.ProspectClinicCompact)[FactionReputationDimension.Trust]; _ = engine.AdvanceDay(world); Assert.Equal(200, once); Assert.Equal(once, world.GetOrCreateReputation(PlayerId, FactionIds.ProspectClinicCompact)[FactionReputationDimension.Trust]); Assert.True(evidence.Applied); }
    [Fact] public void Reputation_dimensions_remain_independent() { var reputation = new FactionReputationState(PlayerId, FactionIds.ProspectClinicCompact); reputation.Adjust(FactionReputationDimension.Fear, 800); reputation.Adjust(FactionReputationDimension.Trust, -300); reputation.Adjust(FactionReputationDimension.Respect, 600); Assert.Equal(800, reputation[FactionReputationDimension.Fear]); Assert.Equal(-300, reputation[FactionReputationDimension.Trust]); Assert.Equal(600, reputation[FactionReputationDimension.Respect]); Assert.Equal("feared", reputation.DerivedStanding); }
    [Fact] public void Disguise_evaluation_is_observer_specific() { var disguise = new DisguiseIdentityState(StableIdFactory.Create("test", "disguise"), PlayerId, FactionIds.BlackwaterRecoveryAuthority, new SortedSet<string>(["pass"], StringComparer.Ordinal), new SortedSet<string>(["industrial"], StringComparer.Ordinal), 700, true); var evaluator = new DisguiseEvaluator(); DisguiseObservationState casual = evaluator.Evaluate(disguise, StableIdFactory.Create("test", "casual"), FactionIds.Player, 250, 100, 0, 1); DisguiseObservationState guard = evaluator.Evaluate(disguise, StableIdFactory.Create("test", "guard"), FactionIds.Player, 900, 900, 500, 1); Assert.NotEqual(casual.Evaluation, guard.Evaluation); Assert.Equal(FactionIds.BlackwaterRecoveryAuthority, casual.BelievedFactionId); Assert.Equal(FactionIds.Player, guard.BelievedFactionId); }
    [Fact] public void Player_relevant_conflict_is_reserved_for_playable_resolution() { var conflict = new StrategicConflictState(StableIdFactory.Create("test", "conflict"), FactionIds.BlackwaterRecoveryAuthority, FactionIds.ProspectClinicCompact, Phase15Content.MeridianRelayLocationId, StrategicConflictStage.Pressure); conflict.SetPlayerRelevance(800); Assert.True(conflict.ReservedForPlayableEncounter); }
    [Fact] public void Market_projection_uses_society_as_authority() { SocietyWorldState society = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var items = new ItemWorldState(); IReadOnlyList<SocietyMarketProjection> projection = new Phase15SocietyEconomyBridge().Project(society, items); Assert.Equal(3, projection.Count); SettlementEconomyState economy = items.GetEconomy(Phase15Content.ProspectSettlementId); Assert.Equal(society.GetSettlement(Phase15Content.ProspectSettlementId).TaxPermille, economy.TaxPolicy.PurchaseTaxPermille); }
    [Fact] public void Control_transfer_updates_both_factions_and_settlement() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var command = new TransferSettlementControlCommand(StableIdFactory.Create("test", "transfer"), world.Revision, Phase15Content.RedQuarrySettlementId, FactionIds.ProspectClinicCompact); SocietyCommandResult result = new SocietyCommandProcessor().Execute(world, command); Assert.Equal(SocietyCommandStatus.Committed, result.Status); Assert.Equal(FactionIds.ProspectClinicCompact, world.GetSettlement(Phase15Content.RedQuarrySettlementId).ControllingFactionId); Assert.Contains(Phase15Content.RedQuarrySettlementId, world.GetFaction(FactionIds.ProspectClinicCompact).ControlledSettlements); }
    [Fact] public void Stale_command_revision_is_rejected_without_mutation() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); StateChecksum before = world.ComputeChecksum(); var command = new ChangeFactionPolicyCommand(StableIdFactory.Create("test", "stale"), world.Revision + 1, FactionIds.ProspectClinicCompact, "open-care", 500); SocietyCommandResult result = new SocietyCommandProcessor().Execute(world, command); Assert.Equal(SocietyCommandStatus.Rejected, result.Status); Assert.Equal(before, world.ComputeChecksum()); }
    [Fact] public void Long_simulation_is_deterministic() { SocietyWorldState first = Phase15Content.CreateRegressionWorld(Seed, PlayerId); SocietyWorldState second = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var firstEngine = new SocietySimulationEngine(Seed); var secondEngine = new SocietySimulationEngine(Seed); _ = firstEngine.AdvanceDays(first, 365); _ = secondEngine.AdvanceDays(second, 365); Assert.Equal(first.ComputeChecksum(), second.ComputeChecksum()); }
    [Fact] public void Evidence_only_crime_can_be_reported_without_omniscience() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); StableId evidenceId = StableIdFactory.Create("test", "camera-record"); var command = new RecordCrimeCommand(StableIdFactory.Create("test", "evidence-crime"), world.Revision, CrimeKind.Espionage, FactionIds.BlackwaterRecoveryAuthority, Phase15Content.BlackwaterSettlementId, PlayerId, 700, [], 800, [evidenceId]); SocietyCommandResult result = new SocietyCommandProcessor().Execute(world, command); Assert.Equal(SocietyCommandStatus.Committed, result.Status); _ = new SocietySimulationEngine(Seed).AdvanceDay(world); Assert.Equal(CrimeStatus.WarrantIssued, world.GetCrime(command.Id).Status); }
    [Fact] public void Control_transfer_updates_territory_and_service_ownership() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var command = new TransferSettlementControlCommand(StableIdFactory.Create("test", "transfer-territory"), world.Revision, Phase15Content.RedQuarrySettlementId, FactionIds.ProspectClinicCompact); _ = new SocietyCommandProcessor().Execute(world, command); TerritoryClaimState claim = world.TerritoryClaims.Single(value => value.LocationId == Phase15Content.RedQuarrySettlementId && value.Kind == TerritoryAuthorityKind.Control); Assert.Equal(FactionIds.ProspectClinicCompact, claim.FactionId); Assert.All(world.GetSettlement(Phase15Content.RedQuarrySettlementId).Services, service => Assert.Equal(FactionIds.ProspectClinicCompact, service.OwnerFactionId)); }
    [Fact] public void Society_relationships_prevent_blanket_cross_faction_hostility() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); var resolver = new SocietyFactionRelationResolver(world); Assert.True(resolver.IsHostile(FactionIds.BlackwaterRecoveryAuthority, FactionIds.Player)); Assert.False(resolver.IsHostile(FactionIds.ProspectClinicCompact, FactionIds.Player)); Assert.False(resolver.IsHostile(FactionIds.ProspectClinicCompact, FactionIds.RedQuarryCooperative)); Assert.True(resolver.IsFriendly(FactionIds.ProspectClinicCompact, FactionIds.RedQuarryCooperative)); }
    [Fact] public void Validator_accepts_the_regression_world() { SocietyWorldState world = Phase15Content.CreateRegressionWorld(Seed, PlayerId); SocietyValidationReport report = new SocietyValidator().Validate(world, Phase15Content.Set("medical-site", "water-source", "industrial-site", "machinery", "road", "fuel-source")); Assert.True(report.IsValid, string.Join("; ", report.Issues.Select(value => value.Message))); }
}
